-- Запись релиза в журнал (notified_at NULL — бот уведомит админа на старте).
-- +goose StatementBegin
INSERT INTO releases (version, released_on, title, public_notes, tech_notes) VALUES (
  '2.67.0',
  '2026-08-04',
  'Оформление 2.0: восемь тем, своя тема с сохранением, рамки, папки фонов и общая галерея',
  E'Вместо пары «светлая/тёмная» — восемь готовых тем с живым предпросмотром: тёмные Ночь, Графит, Индиго и Контраст, светлые День, Бумага, Небо и Контраст.\n\nЛюбой цвет можно поправить под себя: встроенная тема при этом копируется в «Свою тему», исходная остаётся на месте. Свою тему можно сохранить под именем — вместе с фоном и настройками карточек. Режим «как в системе» теперь выбирает пару тем: какую показывать в светлом режиме, какую в тёмном.\n\nПоявились цвет кнопок и рамки — отдельно для карточек и кнопок. Рамка рисуется внутрь блока, поэтому при её включении ничего не разъезжается. Ещё есть сборка темы по одному цвету и предупреждение, если текст на фоне читается плохо.\n\nФоны: свои картинки теперь раскладываются по вложенным папкам со сворачиванием, появилась общая галерея от администратора, а к фону можно задать масштаб и смещение (для «по центру» и «замостить») или точку фокуса (для «заполнить» — какая часть картинки останется видимой). Блок «Оформление» запоминает, свёрнут он или нет.',
  E'Модель хранения: тема — набор токенов, выставляемых CSS-переменными на <html> (shared/themes.ts). Раньше каждая новая настройка означала колонку в user_settings (их набралось восемь при двух темах); теперь оформление — один JSONB на режим входа: appearance и web_appearance. Миграция 0078 переносит туда прежние text_color_*/bg_color_*/card_* — вид ни у кого не меняется.\n\nВстроенные темы живут в коде фронтенда, в базе только id. Своя тема — черновик state.draft на сервере: правка цвета копирует текущую тему и переключает на черновик, встроенную на месте не меняем. Сохранённые темы — user_themes (токены + снимок фона), имя уникально, повторное сохранение перезаписывает.\n\nРамки — box-shadow: inset, а НЕ border: тень не влияет на размеры вообще, поэтому включение рамки не разъезжает вёрстку. Селекторы те же, что у «стекла», плюс .section и .card; включаются атрибутами data-card-border / data-btn-border.\n\nФоны: background_folders (вложенность, сворачивание на папке, рекурсивная защита от переноса папки в саму себя), gallery_categories/gallery_images для общей галереи с экраном в Админке и раздачей /uploads/gallery/. Размещение — bg_scale/bg_offset_*/bg_focal_* в user_settings; «заполнить» остаётся cover (картинка не сжимается, а обрезается), точка фокуса решает, что видно. Миниатюры готовит браузер (canvas → webp) и шлёт вместе с оригиналом: обработки изображений на сервере нет, тянуть библиотеку ради превью не стали.\n\nПопутно: курсы валют вынесены в общий пакет internal/rates ещё в 2.66; здесь из httpapi/converter.go ушли остатки. Свёрнутость блока настроек — существующий механизм ui_collapsed (ключ settings, id 1), в белый список приложений добавлено значение settings.\n\nПроверено: API (темы, черновик, сохранение, папки с 409 на петлю, размещение, галерея с загрузкой и превью, раздача файла) и в браузере — переключение тем на лету, рамка 4px без изменения ширины блока (728px до и после), свёрнутость переживает перезагрузку, фон из общей галереи применяется.'
);
-- +goose StatementEnd

-- +goose Down
DELETE FROM releases WHERE version = '2.67.0';
